import { decimatorSurvivorAt, decimatorSurvivorCount } from '../chain/decimator-sampling.js';
const fields = new WeakMap();
function fieldModel(snapshot) {
  if (fields.has(snapshot)) return fields.get(snapshot);
  const known = new Map((snapshot.battleEntries ?? []).map(entry => [String(entry.entryId), entry]));
  const total = snapshot.fieldEntries ?? snapshot.entrants;
  const survivors = snapshot.sampling && snapshot.fieldEntries != null
    ? new Set(Array.from({ length: Number(decimatorSurvivorCount(total)) }, (_, index) =>
      Number(decimatorSurvivorAt(snapshot.rngWord, snapshot.level, total, index))))
    : new Set((snapshot.battleEntries ?? []).filter(entry => entry.eligible).map(entry => Number(entry.entryId)));
  const field = { known, total, survivors, selected: [...survivors].sort((a, b) => a - b) };
  fields.set(snapshot, field); return field;
}

/** Include unvisited slots too. Generated recipients only exist once their slot is drawn.
 * Page the full id space instead of allocating up to 2^40 cards. */
export function decimatorFieldPage(snapshot, { offset = 0, limit = 25, filter = 'all' } = {}) {
  const { known, total, survivors, selected } = fieldModel(snapshot);
  const row = entryId => known.get(String(entryId)) ?? {
    entryId: String(entryId), address: null, generated: entryId > snapshot.entrants,
    eligible: snapshot.survivorCount == null ? null : survivors.has(entryId),
    stack: snapshot.generatedStackCount && BigInt(snapshot.generatedStackCount) > 0n
      ? String(BigInt(snapshot.generatedStackTotal) / BigInt(snapshot.generatedStackCount)) : '0',
    peak: null, score: null,
  };
  if (filter === 'survivors') return { total: selected.length, rows: selected.slice(offset, offset + limit).map(row) };
  const count = filter === 'out' ? total - selected.length : total;
  // Offset among eliminated ids -> absolute id; at most 1,000 selected ids to skip.
  let first = Math.max(0, offset) + 1;
  if (filter === 'out') for (const id of selected) { if (id <= first) first++; else break; }
  const rows = [];
  for (let entryId = first; entryId <= total && rows.length < limit; entryId++) {
    if (filter !== 'out' || !survivors.has(entryId)) rows.push(row(entryId));
  }
  return { total: count, rows };
}

/** Score is a high-water mark sampled after a shooter, never the ending bankroll. */
export function decimatorStandings(replay, completedHands = 0) {
  return replay.entries.map(entry => ({ ...entry,
    current: entry.checkpoints[Math.min(completedHands, entry.handsPlayed)],
    ended: completedHands >= entry.handsPlayed,
  })).sort((a, b) => {
    const left = BigInt(a.current.rankScore); const right = BigInt(b.current.rankScore);
    if (left !== right) return left > right ? -1 : 1;
    const lt = BigInt(a.tieKey ?? a.entryId); const rt = BigInt(b.tieKey ?? b.entryId);
    return lt === rt ? 0 : lt > rt ? -1 : 1;
  });
}
